<template><view v-if="error" class="persistent-error panel"><view><text class="error-title">{{ error.type || '任务执行失败' }}</text><text class="error-stage">{{ status }}</text></view><text class="error-message">{{ error.message || error }}</text><view class="actions"><button class="ghost small" @click="$emit('copy',error)">复制错误</button><button class="primary small" @click="$emit('queue')">前往队列处理</button></view></view></template>
<script>export default {name:'PersistentError',props:{error:{type:[Object,String],default:null},status:{type:String,default:''}},emits:['copy','queue']}</script>
